PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, password TEXT NOT NULL, name TEXT NOT NULL, email TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', role TEXT NOT NULL DEFAULT 'user', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS addresses(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),recipient TEXT NOT NULL,phone TEXT NOT NULL,postcode TEXT NOT NULL,address TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY,category_id INTEGER REFERENCES categories(id),name TEXT NOT NULL,description TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>=0),stock INTEGER NOT NULL CHECK(stock>=0),image TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS product_images(id INTEGER PRIMARY KEY,product_id INTEGER REFERENCES products(id),image TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS carts(id INTEGER PRIMARY KEY,user_id INTEGER UNIQUE REFERENCES users(id));
CREATE TABLE IF NOT EXISTS cart_items(id INTEGER PRIMARY KEY,cart_id INTEGER REFERENCES carts(id),product_id INTEGER REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity>0),UNIQUE(cart_id,product_id));
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id),status TEXT NOT NULL CHECK(status IN ('PENDING','PAID','CANCELLED','REFUNDED','FAILED')),total INTEGER NOT NULL,recipient TEXT NOT NULL,phone TEXT NOT NULL,postcode TEXT NOT NULL,address TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items(id INTEGER PRIMARY KEY,order_id INTEGER REFERENCES orders(id),product_id INTEGER REFERENCES products(id),name TEXT NOT NULL,price INTEGER NOT NULL,quantity INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY,order_id INTEGER REFERENCES orders(id),method TEXT NOT NULL,card_id INTEGER REFERENCES virtual_cards(id),requested_amount INTEGER NOT NULL,approved_amount INTEGER,status TEXT NOT NULL,reason TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS virtual_cards(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id),number TEXT UNIQUE NOT NULL,expiry TEXT NOT NULL,pin TEXT NOT NULL,balance INTEGER NOT NULL CHECK(balance>=0));
CREATE TABLE IF NOT EXISTS wallets(user_id INTEGER PRIMARY KEY REFERENCES users(id),balance INTEGER NOT NULL CHECK(balance>=0));
CREATE TABLE IF NOT EXISTS wallet_transactions(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id),amount INTEGER NOT NULL,kind TEXT NOT NULL,order_id INTEGER REFERENCES orders(id),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reviews(id INTEGER PRIMARY KEY,product_id INTEGER REFERENCES products(id),user_id INTEGER REFERENCES users(id),rating INTEGER CHECK(rating BETWEEN 1 AND 5),body TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS posts(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id),title TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS comments(id INTEGER PRIMARY KEY,post_id INTEGER REFERENCES posts(id) ON DELETE CASCADE,user_id INTEGER REFERENCES users(id),body TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS attachments(id INTEGER PRIMARY KEY,post_id INTEGER REFERENCES posts(id) ON DELETE CASCADE,original_name TEXT NOT NULL,stored_name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS coupons(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,discount INTEGER NOT NULL);
